typedef struct Edge {
    int to;
    struct Edge* next;
} Edge;

Edge* adj[MAXN];
int parent[MAXN][LOG];
int depth[MAXN];
int n, q;

void add_edge(int u, int v) {
    Edge* e = (Edge*)malloc(sizeof(Edge));
    e->to = v;
    e->next = adj[u];
    adj[u] = e;

    e = (Edge*)malloc(sizeof(Edge));
    e->to = u;
    e->next = adj[v];
    adj[v] = e;
}

void dfs(int u, int p) {
    parent[u][0] = p;
    for (int i = 1; i < LOG; i++) {
        if (parent[u][i-1] != -1)
            parent[u][i] = parent[parent[u][i-1]][i-1];
        else
            parent[u][i] = -1;
    }

    for (Edge* e = adj[u]; e != NULL; e = e->next) {
        int v = e->to;
        if (v != p) {
            depth[v] = depth[u] + 1;
            dfs(v, u);
        }
    }
}

int lca(int u, int v) {
    if (depth[u] < depth[v]) {
        int temp = u;
        u = v;
        v = temp;
    }

    // Lift u up to depth of v
    int diff = depth[u] - depth[v];
    for (int i = 0; i < LOG; i++) {
        if (diff & (1 << i)) {
            u = parent[u][i];
        }
    }

    if (u == v) return u;

    for (int i = LOG-1; i >= 0; i--) {
        if (parent[u][i] != parent[v][i]) {
            u = parent[u][i];
            v = parent[v][i];
        }
    }

    return parent[u][0];
}

int main() {
    scanf("%d %d", &n, &q);

    // Initialize adjacency list
    for (int i = 0; i < n; i++) {
        adj[i] = NULL;
    }

    // Read tree edges
    for (int i = 0; i < n-1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        add_edge(u, v);
    }

    // Initialize parent array
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < LOG; j++) {
            parent[i][j] = -1;
        }
    }

    // Root the tree at 0
    depth[0] = 0;
    dfs(0, -1);

    // Process queries
    for (int i = 0; i < q; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        printf("%d\n", lca(u, v));
    }

    // Free memory
    for (int i = 0; i < n; i++) {
        Edge* e = adj[i];
        while (e != NULL) {
            Edge* temp = e;
            e = e->next;
            free(temp);
        }
