public class Main {
    static int[] parent;
    static int[] depth;
    static int[][] up;
    static List<Integer>[] children;
    static int LOG = 17;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StreamTokenizer st = new StreamTokenizer(br);

        st.nextToken();
        int n = (int) st.nval;

        children = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            children[i] = new ArrayList<>();
        }

        parent = new int[n];
        depth = new int[n];
        up = new int[n][LOG];
        Arrays.fill(parent, -1);

        for (int i = 0; i < n; i++) {
            st.nextToken();
            int id = (int) st.nval;
            st.nextToken();
            int k = (int) st.nval;
            for (int j = 0; j < k; j++) {
                st.nextToken();
                int child = (int) st.nval;
                children[id].add(child);
                parent[child] = id;
            }
        }

        // BFS to set depth and binary lifting table
        int root = 0;
        Queue<Integer> queue = new LinkedList<>();
        queue.add(root);
        depth[root] = 0;
        up[root][0] = root;

        // Initialize
        boolean[] visited = new boolean[n];
        visited[root] = true;

        while (!queue.isEmpty()) {
            int node = queue.poll();
            // up[node][0] already set
            for (int j = 1; j < LOG; j++) {
                up[node][j] = up[up[node][j-1]][j-1];
            }
            for (int child : children[node]) {
                if (!visited[child]) {
                    visited[child] = true;
                    depth[child] = depth[node] + 1;
                    up[child][0] = node;
                    queue.add(child);
                }
            }
        }

        st.nextToken();
        int q = (int) st.nval;

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            st.nextToken();
            int u = (int) st.nval;
            st.nextToken();
            int v = (int) st.nval;
            sb.append(lca(u, v)).append("\n");
        }

        System.out.print(sb);
    }

    static int lca(int u, int v) {
        if (depth[u] < depth[v]) {
            int tmp = u; u = v; v = tmp;
        }
        // Bring u to same depth as v
        int diff = depth[u] - depth[v];
        for (int j = 0; j < LOG; j++) {
            if (((diff >> j) & 1) == 1) {
                u = up[u][j];
            }
        }
        if (u == v) return u;
        for (int j = LOG - 1; j >= 0; j--) {
            if (up[u][j] != up[v][j]) {
                u = up[u][j];
                v = up[v][j];
            }
        }
        return up[u][0];
    }
}

