public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        int n = fs.nextInt();
        List<Integer>[] children = new ArrayList[n];
        for (int i = 0; i < n; i++) children[i] = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int k = fs.nextInt();
            for (int j = 0; j < k; j++) {
                int c = fs.nextInt();
                children[i].add(c);
            }
        }

        int LOG = 1;
        while ((1 << LOG) <= n) LOG++;

        int[][] up = new int[LOG][n];
        int[] depth = new int[n];
        Arrays.fill(up[0], -1);

        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(0);
        depth[0] = 0;
        up[0][0] = -1;

        while (!q.isEmpty()) {
            int v = q.poll();
            for (int to : children[v]) {
                depth[to] = depth[v] + 1;
                up[0][to] = v;
                q.add(to);
            }
        }

        for (int k = 1; k < LOG; k++) {
            for (int v = 0; v < n; v++) {
                int p = up[k - 1][v];
                up[k][v] = (p == -1) ? -1 : up[k - 1][p];
            }
        }

        int queryCount = fs.nextInt();
        for (int i = 0; i < queryCount; i++) {
            int u = fs.nextInt();
            int v = fs.nextInt();
            out.append(lca(u, v, depth, up, LOG)).append('\n');
        }

        System.out.print(out.toString());
    }

    static int lca(int u, int v, int[] depth, int[][] up, int LOG) {
        if (depth[u] < depth[v]) {
            int tmp = u;
            u = v;
            v = tmp;
        }

        int diff = depth[u] - depth[v];
        for (int k = 0; k < LOG; k++) {
            if (((diff >> k) & 1) == 1) {
                u = up[k][u];
            }
        }

        if (u == v) return u;

        for (int k = LOG - 1; k >= 0; k--) {
            if (up[k][u] != up[k][v]) {
                u = up[k][u];
                v = up[k][v];
            }
        }

        return up[0][u];
    }
}
